# Spec 156: do the non-targeting guides match the human genome, and if so, do the samples that carry them show indels at those sites?
#   guides: the 3 NTC sequences of the oligo sheet and the 3 non-targeting guides actually found in the control samples (spec155a)
#   (1) genome matches (hg38, primary chromosomes, both strands): protospacers with up to MAX_MM (3) mismatches; PAM = the 3 bases 3' of the protospacer; a site is "cuttable" when the PAM is NGG (NAG reported too)
#   (2) for every site with an NGG or NAG PAM and RNA-seq coverage: % of reads spanning the predicted cut site (3 bp 5' of the PAM) that carry an insertion or deletion within +/- 10 bp,
#       in the samples that carry the non-targeting guides vs all other samples (Fisher test per site and pooled); the target-gene sites of spec118 give the scale for a real cut
# needs: BSgenome.Hsapiens.UCSC.hg38, BAMs (BAM_DIR), spec155a_NTC_guide_reads.csv
# outputs: spec156_NTC_genome_matches.csv, spec156_NTC_site_indels.csv, spec156_NTC_site_summary.csv, spec156_NTC_indel_per_sample.csv (per sample, pooled over the closest genomic matches of each guide set)
here <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1])))
source(file.path(here, "repro_common.R")); suppressPackageStartupMessages({ library(GenomicAlignments); library(Rsamtools); library(Biostrings); library(BSgenome.Hsapiens.UCSC.hg38) }); options(width = 220)
BAM_DIR <- Sys.getenv("BAM_DIR", unset = "/sc/arion/scratch/giottb01/CROPseq_validation_bulkRNA/work/bam"); MAX_MM <- as.integer(Sys.getenv("MAX_MM", "3")); NCORE <- as.integer(Sys.getenv("NCORE", "6")); WIN <- 10; MINC <- 20
g <- data.frame(guide = c(paste0("NTC_sheet_g", 1:3), paste0("NTC_found_g", 1:3)), seq = c("AAGAAGAATTGGGGATGATG", "AAGAAGGGCCGTACCCGAAA", "AAGCCATTGTATAACTCCAG", "AAAATTATCGGAAACGGTAG", "AAAATCGATGGGCTGAATCT", "AAAAAGCTTCCGCCTGATGG"), stringsAsFactors = FALSE)
gs <- BSgenome.Hsapiens.UCSC.hg38; chrs <- paste0("chr", c(1:22, "X", "Y", "M")); mf <- file.path(OUT, "spec156_NTC_genome_matches.csv")
if (!file.exists(mf) || Sys.getenv("REMAP", "0") == "1") { one <- function(ch) { s <- gs[[ch]]; do.call(rbind, lapply(seq_len(nrow(g)), function(i) { p <- DNAString(g$seq[i]); do.call(rbind, lapply(c("+", "-"), function(sd) { m <- matchPattern(if (sd == "+") p else reverseComplement(p), s, max.mismatch = MAX_MM, with.indels = FALSE); if (!length(m)) return(NULL); st <- start(m); en <- end(m); ok <- st >= 4 & en <= length(s) - 3; st <- st[ok]; en <- en[ok]; if (!length(st)) return(NULL)
      site <- as.character(Views(s, st, en)); if (sd == "-") site <- as.character(reverseComplement(DNAStringSet(site))); pam <- if (sd == "+") as.character(Views(s, en + 1, en + 3)) else as.character(reverseComplement(DNAStringSet(Views(s, st - 3, st - 1))))
      data.frame(guide = g$guide[i], chr = ch, start = st, end = en, strand = sd, site = site, PAM = pam, mismatches = mapply(function(a, b) sum(strsplit(a, "")[[1]] != strsplit(b, "")[[1]]), site, g$seq[i]), cut = if (sd == "+") en - 3 else st + 2, stringsAsFactors = FALSE) })) })) }
  M <- do.call(rbind, parallel::mclapply(chrs, one, mc.cores = NCORE)); M$pam_class <- ifelse(grepl("^.GG$", M$PAM), "NGG", ifelse(grepl("^.AG$", M$PAM), "NAG", "other")); write.csv(M, mf, row.names = FALSE) }
M <- read.csv(mf, stringsAsFactors = FALSE); cat("genome matches by guide and number of mismatches (all PAMs):\n"); print(table(M$guide, M$mismatches)); cat("\nwith an NGG PAM:\n"); print(table(factor(M$guide[M$pam_class == "NGG"], g$guide), factor(M$mismatches[M$pam_class == "NGG"], 0:MAX_MM))); cat("\nexact or 1-mismatch matches:\n"); print(M[M$mismatches <= 1, ], row.names = FALSE)
nf <- file.path(OUT, "spec155a_NTC_guide_reads.csv"); if (!file.exists(nf)) { cat("\nspec155a_NTC_guide_reads.csv not found yet: run spec155a first for the indel comparison\n"); quit(save = "no") }
NR <- read.csv(nf, stringsAsFactors = FALSE); tot <- tapply(NR$reads[grepl("found", NR$guide)], NR$sample[grepl("found", NR$guide)], sum); CAR <- names(tot)[tot >= 20]; ids <- grep("^(H2052|MSTO|H2452|H28)_[A-Za-z0-9]+_R[0-9]+$", unique(NR$sample), value = TRUE); cat(sprintf("\nsamples carrying the non-targeting guides (>= 20 reads): %d of %d: %s\n", sum(ids %in% CAR), length(ids), paste(intersect(ids, CAR), collapse = ", ")))
S <- M[M$pam_class %in% c("NGG", "NAG"), ]; S$id <- sprintf("%s|%s:%d|%s|%dmm|%s", S$guide, S$chr, S$cut, S$strand, S$mismatches, S$pam_class); gr <- GRanges(S$chr, IRanges(S$cut - WIN, S$cut + WIN)); names(gr) <- S$id; bam <- setNames(file.path(BAM_DIR, ids, paste0(ids, "_Aligned.sortedByCoord.out.bam")), ids)
cnt <- function(s) { prm <- ScanBamParam(which = gr, flag = scanBamFlag(isSecondaryAlignment = FALSE, isUnmappedQuery = FALSE, isDuplicate = NA)); ga <- readGAlignments(bam[[s]], param = prm, with.which_label = TRUE); if (!length(ga)) return(NULL); wl <- as.character(mcols(ga)$which_label); key <- sprintf("%s:%d-%d", S$chr, S$cut - WIN, S$cut + WIN)
  do.call(rbind, lapply(seq_len(nrow(S)), function(j) { a <- ga[wl == key[j]]; if (!length(a)) return(NULL); cg <- cigar(a); st <- start(a); Mr <- cigarRangesAlongReferenceSpace(cg, pos = st, ops = c("M", "=", "X", "D")); cov <- any(start(Mr) <= S$cut[j] & end(Mr) >= S$cut[j] + 1); Dl <- cigarRangesAlongReferenceSpace(cg, pos = st, ops = "D"); In <- cigarRangesAlongReferenceSpace(cg, pos = st, ops = "I")
    hd <- any(end(Dl) >= S$cut[j] - WIN & start(Dl) <= S$cut[j] + WIN); hi <- any(start(In) >= S$cut[j] - WIN & start(In) <= S$cut[j] + WIN); data.frame(sample = s, id = S$id[j], n_cover = sum(cov), n_indel = sum(cov & (hd | hi))) })) }
C <- do.call(rbind, parallel::mclapply(ids, cnt, mc.cores = NCORE)); C$carrier <- C$sample %in% CAR; write.csv(C, file.path(OUT, "spec156_NTC_site_indels.csv"), row.names = FALSE)
A <- do.call(rbind, lapply(split(C, C$id), function(d) { a <- d[d$carrier, ]; b <- d[!d$carrier, ]; na <- sum(a$n_cover); nb <- sum(b$n_cover); ia <- sum(a$n_indel); ib <- sum(b$n_indel); data.frame(id = d$id[1], carrier_reads = na, carrier_indel = ia, carrier_pct = 100 * ia / max(1, na), other_reads = nb, other_indel = ib, other_pct = 100 * ib / max(1, nb), p = if (na >= MINC && nb >= MINC) fisher.test(matrix(c(ia, na - ia, ib, nb - ib), 2), alternative = "greater")$p.value else NA) }))
PS <- do.call(rbind, lapply(split(C, list(C$sample, ifelse(grepl("found", C$id), "found", "sheet")), drop = TRUE), function(d) data.frame(sample = d$sample[1], set = if (grepl("found", d$id[1])) "found" else "sheet", sites_covered = sum(d$n_cover > 0), n_cover = sum(d$n_cover), n_indel = sum(d$n_indel), indel_pct = 100 * sum(d$n_indel) / max(1, sum(d$n_cover))))); write.csv(PS, file.path(OUT, "spec156_NTC_indel_per_sample.csv"), row.names = FALSE)
A <- cbind(S[match(A$id, S$id), c("guide", "chr", "cut", "strand", "site", "PAM", "mismatches", "pam_class")], A[, -1]); A$fdr <- p.adjust(A$p, "BH"); A <- A[order(A$p), ]; write.csv(A, file.path(OUT, "spec156_NTC_site_summary.csv"), row.names = FALSE)
cat(sprintf("\nsites with an NGG or NAG PAM (guides found and sheet sequences): %d; with RNA-seq coverage (>= %d reads in carriers and in the other samples): %d\n", nrow(S), MINC, sum(!is.na(A$p)))); x <- A[!is.na(A$p), ]; cat(sprintf("pooled over those sites: carriers %d indel reads of %d (%.3f%%); other samples %d of %d (%.3f%%); Fisher p %.3g\n", sum(x$carrier_indel), sum(x$carrier_reads), 100 * sum(x$carrier_indel) / sum(x$carrier_reads), sum(x$other_indel), sum(x$other_reads), 100 * sum(x$other_indel) / sum(x$other_reads), fisher.test(matrix(c(sum(x$carrier_indel), sum(x$carrier_reads) - sum(x$carrier_indel), sum(x$other_indel), sum(x$other_reads) - sum(x$other_indel)), 2), alternative = "greater")$p.value))
cat("sites with FDR < 0.05:", sum(x$fdr < 0.05, na.rm = TRUE), "| nominal p < 0.05:", sum(x$p < 0.05), "\ntop sites:\n"); print(head(x, 15), digits = 3, row.names = FALSE); cat("\nby mismatches (NGG only): pooled indel % carriers vs others\n"); y <- x[x$pam_class == "NGG", ]; y$mismatches <- paste(ifelse(grepl("found", y$guide), "found", "sheet"), y$mismatches); print(do.call(rbind, lapply(split(y, y$mismatches), function(d) data.frame(mismatches = d$mismatches[1], sites = nrow(d), carrier_pct = 100 * sum(d$carrier_indel) / sum(d$carrier_reads), other_pct = 100 * sum(d$other_indel) / sum(d$other_reads)))), digits = 3, row.names = FALSE)
